import{_ as i,a0 as a,w as s,s as l,ao as c,I as p,x as o,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux cp 命令的15個示例 - 創建文件和目錄的副本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux cp 命令的15個示例 - 創建文件和目錄的副本 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux cp 命令的15個示例 - 創建文件和目錄的副本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux cp 命令的15個示例 - 創建文件和目錄的副本 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories","title":"Linux cp 命令的15個示例 - 創建文件和目錄的副本","tag":"201403","desc":""},"relativePath":"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories.md","filePath":"[post].md"}'),g={name:"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories.md"};function d(m,t,h,f,u,_){const e=a("Link");return s(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-cp-命令的15個示例-創建文件和目錄的副本" tabindex="-1">Linux cp 命令的15個示例 - 創建文件和目錄的副本 <a class="header-anchor" href="#linux-cp-命令的15個示例-創建文件和目錄的副本" aria-label="Permalink to “Linux cp 命令的15個示例 - 創建文件和目錄的副本”">​</a></h1><p>拷貝文件和目錄是每一個操作系統的基本指令。備份行為基本上是創建文件和目錄的副本。在Linux系統下，我們可以用<strong>cp</strong>命令來實現。</p><h3 id="copy-命令是什麼" tabindex="-1">copy 命令是什麼 <a class="header-anchor" href="#copy-命令是什麼" aria-label="Permalink to “copy 命令是什麼”">​</a></h3><p>正如我們在上文提到的，<strong>cp</strong>是一個用來創建文件和目錄副本的命令。在這裏我們提供了一些在日常操作中可能用到的cp命令的實例。</p><h3 id="_1-不帶任何參數下-運行cp" tabindex="-1">1. 不帶任何參數下，運行cp <a class="header-anchor" href="#_1-不帶任何參數下-運行cp" aria-label="Permalink to “1. 不帶任何參數下，運行cp”">​</a></h3><p>這是 cp 命令最基礎的使用。 拷貝名為 myfile.txt 從一個位置到另一個位置，我們可以像這樣子輸入：</p><pre><code>$ cp myfile.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_default.png" alt="Copy without options"></p><p>如果我們沒有輸入絕對路徑，這意味着我們正在當前目錄下拷貝一個文件。在上面的實例中，<strong>myfile.txt</strong>位於<strong>/home/pungki/Documents</strong>目錄下。如果我們當前目錄正是<strong>/home/pungki/Documets</strong>,那麼沒有必要輸入<strong>/home/pungki/Documents/myfile.txt</strong>來拷貝文件。當<strong>/home/pungki/office</strong>是一個目錄，則文件會拷貝到裏面。</p><h4 id="_2-同時拷貝多個文件" tabindex="-1">2. 同時拷貝多個文件 <a class="header-anchor" href="#_2-同時拷貝多個文件" aria-label="Permalink to “2. 同時拷貝多個文件”">​</a></h4><p>要在同時拷貝多個文件，我們只需要將多個文件用空格隔開。如下示例：</p><pre><code>$ cp file_1.txt file_2.txt file_3.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_multiple_file.png" alt="Copying multiple files"></p><h4 id="_3-拷貝一個目錄" tabindex="-1">3. 拷貝一個目錄 <a class="header-anchor" href="#_3-拷貝一個目錄" aria-label="Permalink to “3. 拷貝一個目錄”">​</a></h4><p>要拷貝一個目錄的話會有點棘手。你需要添加 <strong>-r</strong> 或者 <strong>-R</strong> 選項來實現。<strong>-r</strong>或<strong>-R</strong> 選項表明遞歸操作。無論該目錄是否為空目錄，<strong>這個選項都是必要的</strong>。如下示例：</p><pre><code>$ cp -r directory_1 /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_directory.png" alt="Copy directory"></p><p>需要注意的一件事，你需要<strong>移除在目錄名尾部的斜槓</strong>。否則你會收到類似的錯誤信息<strong>cp: omitting directory‘directory_1/</strong>’</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_directory_error.png" alt="Copy directory error"></p><p>如果你收到錯誤信息，則目錄不會被拷貝到目標文件夾。</p><h4 id="_4-創建文件的硬鏈接-而不是拷貝它們" tabindex="-1">4. 創建文件的硬鏈接，而不是拷貝它們#### <a class="header-anchor" href="#_4-創建文件的硬鏈接-而不是拷貝它們" aria-label="Permalink to “4. 創建文件的硬鏈接，而不是拷貝它們####”">​</a></h4><p>拷貝文件意味着你必須使用一些存儲空間來儲存拷貝的文件。有時候出於某種原因，你可能想要創建“快捷方式”或者鏈接到文件，而不是拷貝它們。要做到這一點，我們可以使用<strong>-l</strong>選項。</p><pre><code>$ cp -l file_4.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks.png" alt="Copy hardlinks"></p><p>從上圖看出，我們看到<strong>file_4.txt</strong>的硬鏈接已經拷貝到<strong>/home/pungki/office/file_4.txt</strong>。標記有同樣的 inode, <strong>835386</strong>。但是請注意，硬鏈接不能用來創建目錄。下面讓我們看一個例子。</p><p><em>原目錄 directory_1 的 inode 值是 278230</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_dir_1_ori.png" alt="Inode number of original directory"></p><p><em>原文件 file_5.txt 的 inode 值是 279231</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_file_5_ori.png" alt="Original inode number of file"></p><p><em>對 directory_1 執行 cp 命令</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_rl_dir.png" alt="Copy using -rl options"></p><p><em>拷貝的 directory_1副本的 inode 值是 274800</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_dir_1_result.png" alt="Inode number of copied directory"></p><p><em>拷貝的 file_5.txt副本的 inode 值是 279231。跟它的原文件一樣</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_file_5_result.png" alt="Inode number of copied file"></p><h4 id="_5-創建文件的符號鏈接" tabindex="-1">5. 創建文件的符號鏈接 <a class="header-anchor" href="#_5-創建文件的符號鏈接" aria-label="Permalink to “5. 創建文件的符號鏈接”">​</a></h4><p>也有一種鏈接叫做 <strong>軟鏈接</strong> 或 <strong>符號鏈接</strong>。我們用 <strong>-s</strong> 選項來實現。下面是命令的示例。</p><pre><code>$ cp -s /home/pungki/Documents/file_6.txt file_6.txt
</code></pre><p>創建符號鏈接只能在當前目錄下進行。在上面的截圖中，我們想要創建符號鏈接 <strong>/home/pungki/office/file_6.txt 指向原文件 /home/pungki/Documents/file_6.txt</strong>。但是為了創建符號鏈接，<strong>我必須</strong>在將/home/pungki/office作為目標目錄。一旦我設法進入目錄，我就可以向上面一樣運行 cp <strong>-s</strong> 命令。</p><p>現在你列出文件詳情，你會看到<strong>/home/pungki/office/file_6.txt</strong>指向了原文件。在其文件名後標記了箭頭符號。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_symlinks.png" alt="Symbolic links"></p><h4 id="_6-不隨符號鏈接拷貝原文件" tabindex="-1">6. 不隨符號鏈接拷貝原文件 <a class="header-anchor" href="#_6-不隨符號鏈接拷貝原文件" aria-label="Permalink to “6. 不隨符號鏈接拷貝原文件”">​</a></h4><p>[譯註:意思是隻拷貝符號鏈接文件]</p><p>我們可以用 <strong>-P</strong> 選項來實現。當對符號鏈接使用 cp 命令，它會照原樣拷貝它自身。來看看下面的示例。</p><pre><code>$ cp -P file_6.txt ./movie
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_P.png" alt="Copy using -P option"></p><p>如你所見，cp 命令照原樣拷貝<strong>file_6.txt</strong>自身。文件類型仍然是一個符號鏈接。</p><h4 id="_7-隨符號鏈接拷貝原文件" tabindex="-1">7. 隨符號鏈接拷貝原文件 <a class="header-anchor" href="#_7-隨符號鏈接拷貝原文件" aria-label="Permalink to “7. 隨符號鏈接拷貝原文件”">​</a></h4><p>現在我們可以試一下<strong>-L</strong>選項。基本上，這個剛好與上面的 -P 選項 <strong>相反</strong>。下面是個示例：</p><pre><code>$ cp -L file_6.txt ./movie
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_L.png" alt="Copy using -L option"></p><p>使用這個選項，拷貝的文件將會和<strong>file_6.txt</strong>原文件一樣。我們可以從文件大小看出來。拷貝的文件有<strong>50 字節</strong>而當<strong>file_6.txt</strong>作為符號鏈接時文件大小隻有<strong>33 字節</strong>。</p><h4 id="_8-文件歸檔" tabindex="-1">8. 文件歸檔 <a class="header-anchor" href="#_8-文件歸檔" aria-label="Permalink to “8. 文件歸檔”">​</a></h4><p>當我們去拷貝一個目錄時，我們會用<strong>-r</strong>或者<strong>-R</strong>選項。但是我們也可以用<strong>-a</strong>選項來歸檔文件。這樣會創建文件和目錄的<strong>準確套錄</strong>，如果有的話也可以包括符號鏈接。下面是示例：[譯註：-a 會保留原文件或目錄的屬性]</p><pre><code>$ cp -a directory_1/ /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_a.png" alt="Copy using -a option"></p><p>上列的命令會拷貝一個名為 directory_1 的目錄到<strong>/home/pungki/office</strong>目錄下。如你所見，<strong>file_6.txt</strong>依然作為符號鏈接被複制。</p><h4 id="_9-顯示正在做什麼" tabindex="-1">9. 顯示正在做什麼 <a class="header-anchor" href="#_9-顯示正在做什麼" aria-label="Permalink to “9. 顯示正在做什麼”">​</a></h4><p>默認情況下，當拷貝作業成功時，我們僅僅會再次看到命令提示符。如果你想了解在拷貝文件時都發生了什麼，我們可以用 <strong>-v</strong> 選項。</p><pre><code>$ cp -v *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_v.png" alt="Verbose option"></p><p>當我們從當前目錄下拷貝所有的 txt 文件到 <strong>/home/pungki/office</strong> 目錄，<strong>-v</strong>選項會顯示正在操作的過程。這些額外的信息會幫助我們瞭解更多拷貝過程。</p><h4 id="_10-當原文件較目標文件新時拷貝" tabindex="-1">10. 當原文件較目標文件新時拷貝 <a class="header-anchor" href="#_10-當原文件較目標文件新時拷貝" aria-label="Permalink to “10. 當原文件較目標文件新時拷貝”">​</a></h4><p>我們用 <strong>-u</strong>選項來實現。下面是具體示例:</p><pre><code>$ cp -vu *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_u.png" alt="Copy only if newer"></p><p>起初我們看到<strong>file_1.txt 是0字節</strong>大小。然後我們用 vi 編輯，加入一些內容並保存。接下來，我們發現文件大小已經變為了 36 個字節。 與此同時在<strong>/home/pungki/office</strong>目錄中，我們<strong>已經包含了所有</strong>txt文件。當我們用 -u 選項，結合 -v 選項來查看具體操作，cp 命令會只拷貝比目標目錄下新的文件。因此，我們看到<strong>只有 file_1.txt 拷貝到 /home/pungki/office 目錄下</strong>。</p><h4 id="_11-使用交互模式" tabindex="-1">11. 使用交互模式 <a class="header-anchor" href="#_11-使用交互模式" aria-label="Permalink to “11. 使用交互模式”">​</a></h4><p>交互模式下會詢問是否覆蓋目標目錄下的文件。使用 <strong>-i</strong> 選項，啓用交互模式。</p><pre><code>$ cp -ir directory_1/ /home/pungki/office/
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_i.png" alt="Interactive mode"></p><h4 id="_12-創建備份文件" tabindex="-1">12. 創建備份文件 <a class="header-anchor" href="#_12-創建備份文件" aria-label="Permalink to “12. 創建備份文件”">​</a></h4><p>當目標目錄已經含有同名文件，默認情況下 cp 命令會覆蓋目標目錄下的同名文件。使用 <strong>--backup</strong> 選項，cp 命令會為每一個現有的目標文件做一個備份。../office 相對於 /home/pungki/office 。下面是示例：</p><pre><code>$ cp --backup=simple -v *.txt ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_backup.png" alt="Backup option"></p><p>正如我們看到的，<strong>--backup=simple</strong> 選項會創建一個在文件名末尾用波浪符標記(~)的備份文件。<strong>--backup</strong> 選項也有一些其他控制：</p><ul><li><strong>none, off</strong>:從不備份(即使給出 --backup)</li><li><strong>numbered, t</strong>:用編號備份</li><li><strong>existing, nil</strong> :如果編號備份存在則使用編號備份，否者用簡易備份[譯註：也就是用波浪號]</li><li><strong>simple, never</strong> :總是使用簡易備份</li></ul><h4 id="_13-只拷貝文件屬性" tabindex="-1">13. 只拷貝文件屬性 <a class="header-anchor" href="#_13-只拷貝文件屬性" aria-label="Permalink to “13. 只拷貝文件屬性”">​</a></h4><p>cp 命令也提供給我們 <strong>--attributes-only</strong> 選項。顧名思義，這個選項只會拷貝文件名及其屬性，不會拷貝任何數據。下面是示例：</p><pre><code>$ cp --attributes-only file_6.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_attributes_only.png" alt="Copy attributes only"></p><p>從上圖看出， <strong>原文件 file_6.txt 有 50 字節</strong>大小。用了 <strong>--attributes-only</strong>選項，<strong>拷貝的文件只有0字節</strong>大小。這是因為文件內容並沒有拷貝。</p><h3 id="_14-強制拷貝" tabindex="-1">14. 強制拷貝 <a class="header-anchor" href="#_14-強制拷貝" aria-label="Permalink to “14. 強制拷貝”">​</a></h3><p>用了 <strong>-f</strong> 選項會強制進行拷貝操作。如果目標文件不能打開，可以用 <strong>-f</strong> 嘗試一下。</p><pre><code>$ cp -f *.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_f.png" alt="Copy with force"></p><h4 id="_15-在拷貝之前先刪除目標" tabindex="-1">15. 在拷貝之前先刪除目標 <a class="header-anchor" href="#_15-在拷貝之前先刪除目標" aria-label="Permalink to “15. 在拷貝之前先刪除目標”">​</a></h4><p>我們可以用，<strong>--remove-destination 選項</strong> 實現。這個選項與上面的<strong>-f選項形成對照</strong>。如果 cp 命令在目標目錄下發現同名文件， cp 命令會先刪除目標文件，然後再拷貝一份新的。下面是示例：</p><pre><code>$ cp --remove-destination *.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_remove_destination.png" alt="Remove destination option"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>cp 命令是 Linux 下最基礎的命令之一。對於那些想要學習 Linux 的人，必須得把這個命令掌握。當然你也可以在你的終端下鍵入 <strong>man cp</strong> 或者 <strong>cp --help</strong> 來顯示更多幫助信息。</p><hr>`,88)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"http://linoxide.com/linux-command/linux-cp-command/"},{default:r(()=>[...t[0]||(t[0]=[o("http://linoxide.com/linux-command/linux-cp-command/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=o("譯者：",-1)),n(e,{href:"https://github.com/Luoxcat"},{default:r(()=>[...t[2]||(t[2]=[o("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),n(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...t[3]||(t[3]=[o("Mr小眼兒",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const y=i(g,[["render",d]]);export{b as __pageData,y as default};
